import {e,safeURL} from './ui.mjs?v=20261117sharp';
import {homeModuleLabels} from './editorial-model.mjs?v=20261117sharp';
import {serviceEditor,postsEditor,reviewsEditor,teamEditor} from './section-editors.mjs?v=20261117sharp';
export function imageEditor(path,label,value,input){return `<div class="editor-image">${value?`<img src="${safeURL(value)}" alt="Vista previa de ${e(label)}" loading="lazy">`:''}<div><strong>${e(label)}</strong><div class="editor-image-actions">${value?`<button type="button" class="button button-outline" data-crop-path="${e(path)}">Ajustar encuadre</button>`:''}<label class="editor-upload">Subir foto<input type="file" data-upload-path="${e(path)}" accept="image/jpeg,image/png,image/webp"></label></div></div></div>`;}
export function editorialEditor(tab,d,{input,block}){
 const at=path=>path.split('.').reduce((value,key)=>value?.[key],d);
 const image=(path,label='Imagen')=>imageEditor(path,label,at(path),input);
 if(['vender','rentar','comprar'].includes(tab))return serviceEditor(tab,d,{input,block,image});
 if(tab==='posts')return postsEditor(d,{input,block,image});
 if(tab==='reviews')return reviewsEditor(d,{input,block});
 const button=(path)=>input(path+'.buttonLabel','Texto del botón')+input(path+'.buttonHref','Destino del botón · página interna o HTTPS');
 const photos=(path,max)=>`${(at(path)||[]).map((photo,i)=>`<div class="editor-photo-row">${image(path+'.'+i+'.photo','Fotografía '+(i+1))}${path==='clients.items'?'':input(path+'.'+i+'.caption','Texto que acompaña la imagen',{area:true})}${path==='clients.items'?input(path+'.'+i+'.caption','Texto que acompaña la foto',{area:true})+input(path+'.'+i+'.published','Mostrar fotografía',{check:true}):''}<button type="button" class="text-button danger" data-delete-photo="${path}" data-index="${i}">Quitar fotografía</button></div>`).join('')}<button type="button" class="button button-outline" data-add-photo="${path}" ${(at(path)||[]).length>=max?'disabled':''}>Agregar fotografía · ${(at(path)||[]).length}/${max}</button>`;
 const faq=()=>input('faqConfig.title','Título del módulo')+input('faqConfig.intro','Descripción',{area:true})+d.faq.map((q,i)=>`<details class="editor-item"><summary>${e(q.question||'Nueva pregunta')}</summary>${input(`faq.${i}.visible`,'Mostrar pregunta',{check:true})+input(`faq.${i}.category`,'Categoría')+input(`faq.${i}.question`,'Pregunta')+input(`faq.${i}.answer`,'Respuesta',{area:true})}<button type="button" class="text-button danger" data-delete-faq="${i}">Eliminar pregunta</button></details>`).join('')+'<button type="button" class="button button-outline" data-new-faq>Agregar pregunta</button>';
 const process=()=>input('processTitle','Frase principal',{area:true})+d.process.map((step,i)=>block('Etapa '+(i+1),image(`process.${i}.image`)+input(`process.${i}.title`,'Título')+input(`process.${i}.text`,'Descripción',{area:true})+input(`process.${i}.items`,'Puntos · uno por línea',{lines:true}))).join('');
 const module=id=>{
  if(id==='statement')return input('statement.text','Frase de presentación',{area:true})+button('statement');
  if(id==='properties')return '<p>Usa el catálogo activo. Edita aquí su encabezado y botón; las propiedades se gestionan en su sección.</p>'+input('widgets.properties.title','Título')+button('widgets.properties');
  if(id==='reviews')return '<p>Usa las reseñas aprobadas. Los comentarios se moderan en Reseñas.</p>'+input('widgets.reviews.title','Título')+input('widgets.reviews.intro','Descripción · vacío muestra el total de reseñas');
  if(id==='clients')return input('clients.title','Título')+input('clients.intro','Descripción',{area:true})+photos('clients.items',20);
  if(id==='process')return process();
  if(id==='metrics')return input('metrics.title','Título')+input('metrics.intro','Descripción',{area:true})+image('metrics.image','Imagen de fondo')+d.metrics.items.map((item,i)=>block('Cifra '+(i+1),input(`metrics.items.${i}.label`,'Descripción')+input(`metrics.items.${i}.source`,'Origen del número',{choices:{manual:'Número manual',properties:'Total de propiedades activas',team:'Integrantes del equipo',services:'Servicios',locations:'Zonas del catálogo'}})+input(`metrics.items.${i}.value`,'Número · se usa al elegir Número manual',{number:true}))).join('');
  if(id==='living')return input('living.title','Frase principal',{area:true})+button('living')+d.living.photos.map((photo,i)=>block('Imagen '+(i+1),image(`living.photos.${i}.photo`))).join('');
  if(id==='faq')return faq();
  if(id==='transactions')return input('transactions.title','Título')+input('transactions.intro','Descripción',{area:true})+'<p>Las operaciones y las cancelaciones se gestionan en Propiedades. La casilla Visible de Orden y visibilidad controla este módulo en el inicio.</p>';
  if(id==='journal')return input('widgets.journal.title','Título')+input('widgets.journal.intro','Descripción',{area:true});
  return '';
 };
 if(tab==='home')return block('Portada · primera imagen',image('home.photo','Imagen principal')+input('home.title','Frase principal',{area:true})+input('home.intro','Descripción',{area:true})+button('home'))+block('Orden y visibilidad',`<p>Este es el orden del inicio, debajo de la portada. Sube o baja cada módulo y pulsa Publicar para aplicar el cambio. Ocultarlo conserva su contenido.</p><div class="module-sort">${d.home.modules.map((id,i)=>`<div data-home-sort="${id}"><span>${i+1}. ${e(homeModuleLabels[id]||id)}</span><label class="consent"><input type="checkbox" data-module-visible="${id}" ${(d.home.hiddenModules.includes(id)||(id==='transactions'&&d.transactions.visible===false))?'':'checked'}>Visible</label><button type="button" class="text-button" data-move="${id}" data-dir="-1" ${i===0?'disabled':''} aria-label="Subir ${e(homeModuleLabels[id])}">↑</button><button type="button" class="text-button" data-move="${id}" data-dir="1" ${i===d.home.modules.length-1?'disabled':''} aria-label="Bajar ${e(homeModuleLabels[id])}">↓</button></div>`).join('')}</div><label>Agregar módulo<select id="add-module"><option value="">Elige un módulo</option>${Object.keys(homeModuleLabels).filter(id=>!d.home.modules.includes(id)).map(id=>`<option value="${id}">${e(homeModuleLabels[id])}</option>`).join('')}</select></label>`)+d.home.modules.map(id=>`<details class="editor-module" data-home-editor="${id}"><summary>${e(homeModuleLabels[id])}<span>${(d.home.hiddenModules.includes(id)||(id==='transactions'&&d.transactions.visible===false))?'Oculto':'Visible'}</span></summary><div>${module(id)}</div></details>`).join('');
 if(tab==='team')return teamEditor(d,{input,block,image,photos});
 if(tab==='process')return process();if(tab==='faq')return faq();return null;
}
